   const mean = trainSet.length
     ? trainSet.reduce((acc, r) => acc + r.rating, 0) / trainSet.length
     : 0;
   let sum = 0;
   for (const r of split) {
     const diff = mean - r.rating;
     sum += diff * diff;
   }
   return Math.sqrt(sum / split.length);
