           throw new Error(`row ${i} epoch = ${row.epoch}`);
         }
         if (!Number.isFinite(row.trainRMSE) || !Number.isFinite(row.valRMSE)) {
           throw new Error(`row ${i} RMSE is not finite`);
         }
       });
       return history.map((r) => `e${r.epoch}:${fmt(r.trainRMSE)}`).join(" ");
     }),
   );

