    const err=(mu+dot)-r.rating;
    const gu=getGrad(gP,u), gi=getGrad(gQ,i);
    for(let f=0;f<F;f++){ gu[f]+=err*Q[qi+f]+reg*P[pu+f]; gi[f]+=err*P[pu+f]+reg*Q[qi+f]; }
