// Build the sparse-friendly rating matrix.
// Shape: (numUsers + 1) x (maxMovieId + 1), indexed by raw ids, so that
//   ratingMatrix[userId][movieId] === rating
// and an unobserved pair is 0. MovieLens ratings are 1-5, so 0 is unambiguous.
function buildRatingMatrix() {
    const maxMovieId = movies.reduce((max, m) => Math.max(max, m.id), 0);

    ratingMatrix = [];
    for (let u = 0; u <= numUsers; u++) {
        ratingMatrix.push(new Array(maxMovieId + 1).fill(0));
    }

    for (const r of ratings) {
        if (r.userId <= numUsers && r.movieId <= maxMovieId) {
            ratingMatrix[r.userId][r.movieId] = r.rating;
        }
    }
}

input.newString:
// Build the sparse-friendly rating matrix.
// Shape: (numUsers + 1) x (maxMovieId + 1), indexed by raw ids, so that
//   ratingMatrix[userId][movieId] === rating
// and an unobserved pair is 0. MovieLens ratings are 1-5, so 0 is unambiguous
// as a "missing" sentinel: an unobserved cell is never fed to the model.
function buildRatingMatrix() {
    const maxMovieId = movies.reduce((max, m) => Math.max(max, m.id), 0);

    ratingMatrix = [];
    for (let u = 0; u <= numUsers; u++) {
        ratingMatrix.push(new Array(maxMovieId + 1).fill(0));
    }

    for (const r of ratings) {
        if (r.userId <= numUsers && r.movieId <= maxMovieId) {
            ratingMatrix[r.userId][r.movieId] = r.rating;
        }
    }

    // Sparsity of the dense user x movie grid. With U users and M movies the
    // grid has U*M cells; only `ratings.length` of them are observed. The rest
    // are unobserved (not zeros), i.e. a sparsity near 1 means the grid is
    // almost entirely empty — the usual regime for recommenders.
    const U = numUsers; // highest user id (943 for MovieLens 100k)
    const M = movies.length; // number of distinct movies (1682)
    ratingStats = {
        observed: ratings.length,
        cells: U * M,
        sparsity: U * M > 0 ? 1 - ratings.length / (U * M) : 0,
    };
}

