  const epochs = Math.max(1, Math.round(opts.epochs));
  const lr = opts.lr;
  const reg = opts.reg;
  const batchSize = Math.max(1, Math.round(opts.batchSize));

  const F = model.numFactors;
  const P = model.userFactors;
  const Q = model.itemFactors;
