    for (const [i, g] of gQ) {
      const qi = i * F;
      for (let f = 0; f < F; f++) Q[qi + f] -= lr * g[f] * inv;
    }
  };

  for (let epoch = 1; epoch <= epochs; epoch++) {
    for (let k = n - 1; k > 0; k--) {
      const j = Math.floor(Math.random() * (k + 1));
      const tmp = order[k];
      order[k] = order[j];
      order[j] = tmp;
    }

