// Node harness: run week5 data.js + script.js against the real dataset and
// exercise BOTH engines plus the built-in self-checks.
const fs = require("fs");
const path = require("path");
const vm = require("vm");

const WEEK5 = "/home/neferpitu/recsys/RS/RecSys-LLMs/week5";

global.tf = require("@tensorflow/tfjs");
global.window = {};
global.document = {
  getElementById: () => null,
  createElement: () => ({}),
  body: null,
};
global.fetch = async (url) => ({
  ok: true,
  text: async () => fs.readFileSync(path.join(WEEK5, url), "utf8"),
});

let source =
  fs.readFileSync(path.join(WEEK5, "data.js"), "utf8") +
  "\n" +
  fs.readFileSync(path.join(WEEK5, "script.js"), "utf8") +
  `
globalThis.__state = {
  get movies(){return movies}, get ratings(){return ratings},
  get trainSet(){return trainSet}, get valSet(){return valSet}, get testSet(){return testSet},
  get model(){return model}, get trainingHistory(){return trainingHistory},
  get bestCheckpoint(){return bestCheckpoint},
  loadData, splitByTimestamp, runTests,
  initializeFactors, initializeFactorsJS,
  trainMF, trainMFJS, predictRating, selectBestCheckpoint,
  recommendTopK, recallAtK, computeBaselineRMSE, computeRMSEFor,
};
`;

vm.runInThisContext(source, { filename: "week5-combined.js" });

const S = globalThis.__state;

(async () => {
  await global.tf.ready();
  await S.loadData();
  const split = S.splitByTimestamp();
  // Mirror window.onload's state assignment via a second scope-preserving eval:
  // splitByTimestamp returns arrays; assign them through the pipeline by calling
  // the exported renderer-free path.
  globalThis.__state.loadData(); // no-op
  // Assign splits: we cannot write the getters, so run the real onload instead.
  await global.window.onload();

  const t = globalThis.__state;
  const train = t.trainSet, val = t.valSet, test = t.testSet;
  console.log("dataset:", t.movies.length, "movies,", t.ratings.length, "ratings");
  console.log("split:", train.length, "/", val.length, "/", test.length);

  console.log("\n===== built-in self-checks =====");
  const res = t.runTests({ set textContent(v) { console.log(v); } });
  console.log("summary:", res.passed, "pass,", res.failed, "fail,", res.pending, "pending");

  const baseline = t.computeBaselineRMSE(test);

  console.log("\n===== PURE JS SGD ENGINE =====");
  t.initializeFactorsJS(train, 16);
  const histJS = t.trainMFJS(train, val, { epochs: 12, lr: 0.01, reg: 0.05, batchSize: 64 }, test);
  const bestJS = t.selectBestCheckpoint(histJS);
  const jsPred = t.predictRating(train[0].userId, train[0].movieId);
  const jsRecs = t.recommendTopK(train[0].userId, 10);
  const jsRecall = t.recallAtK(10);
  console.log("baseline test RMSE:", baseline.toFixed(4));
  console.log("best epoch:", bestJS.epoch, "val RMSE:", bestJS.valRMSE.toFixed(4), "test RMSE:", bestJS.testRMSE.toFixed(4));
  console.log("beats baseline:", bestJS.testRMSE < baseline);
  console.log("sample prediction:", jsPred.toFixed(4));
  console.log("top-3 JS recs:", jsRecs.slice(0, 3).map(r => r.title + "=" + r.score.toFixed(2)).join(" | "));
  console.log("Recall@10:", jsRecall.overallRecall.toFixed(4), "evalUsers:", jsRecall.perUser.length,
    "unseenIds:", jsRecall.excluded.unseenIds.length, "usersWithoutRelevant:", jsRecall.excluded.usersWithoutRelevant.length);

  console.log("\n===== TENSORFLOW.JS ENGINE =====");
  t.initializeFactors(train, 16);
  const histTF = t.trainMF(train, val, { epochs: 12, lr: 0.01, reg: 0.05, batchSize: 256 }, test);
  const bestTF = t.selectBestCheckpoint(histTF);
  const tfPred = t.predictRating(train[0].userId, train[0].movieId);
  const tfRecs = t.recommendTopK(train[0].userId, 10);
  const tfRecall = t.recallAtK(10);
  console.log("baseline test RMSE:", baseline.toFixed(4));
  console.log("best epoch:", bestTF.epoch, "val RMSE:", bestTF.valRMSE.toFixed(4), "test RMSE:", bestTF.testRMSE.toFixed(4));
  console.log("beats baseline:", bestTF.testRMSE < baseline);
  console.log("sample prediction:", tfPred.toFixed(4));
  console.log("top-3 TF recs:", tfRecs.slice(0, 3).map(r => r.title + "=" + r.score.toFixed(2)).join(" | "));
  console.log("Recall@10:", tfRecall.overallRecall.toFixed(4));
})().catch((e) => { console.error("HARNESS ERROR:", e); process.exit(1); });

