const WEEK5 = "/home/neferpitu/recsys/RS/RecSys-LLMs/week5";
global.tf = require("@tensorflow/tfjs");
global.window = {};
global.document = { getElementById: () => null, createElement: () => ({}), body: null };
global.fetch = async (url) => ({ ok: true, text: async () => fs.readFileSync(path.join(WEEK5, url), "utf8") });

const source =
  fs.readFileSync(path.join(WEEK5, "data.js"), "utf8") + "\n" +
  fs.readFileSync(path.join(WEEK5, "script.js"), "utf8") + `
globalThis.__state = {
  get movies(){return movies}, get trainSet(){return trainSet}, get valSet(){return valSet},
  get testSet(){return testSet},
  loadData, splitByTimestamp, initializeFactorsJS, trainMFJS, selectBestCheckpoint,
  computeBaselineRMSE, computeRMSEFor,
  runJS: (train,val,test,opts)=>{ initializeFactorsJS(train,16); return trainMFJS(train,val,opts,test); },
};
`;
vm.runInThisContext(source, { filename: "combined.js" });

(async () => {
  await global.tf.ready();
  await global.window.onload();
  const S = globalThis.__state;
  const { trainSet: train, valSet: val, testSet: test } = S;
  const baseline = S.computeBaselineRMSE(test);
  console.log("baseline test RMSE:", baseline.toFixed(4));

  const configs = [
    { epochs: 20, lr: 0.01, reg: 0.05, batchSize: 64 },
    { epochs: 30, lr: 0.05, reg: 0.02, batchSize: 256 },
    { epochs: 30, lr: 0.08, reg: 0.02, batchSize: 64 },
    { epochs: 50, lr: 0.05, reg: 0.02, batchSize: 512 },
  ];
  for (const opts of configs) {
    const t0 = Date.now();
    const hist = S.runJS(train, val, test, opts);
    const best = S.selectBestCheckpoint(hist);
    console.log(JSON.stringify(opts), "-> testRMSE", best.testRMSE.toFixed(4),
      "valRMSE", best.valRMSE.toFixed(4), "epoch", best.epoch, `${((Date.now()-t0)/1000).toFixed(1)}s`);
  }
})().catch((e) => { console.error(e); process.exit(1); });

