const F = 16;
function rmse(data, P, Q, mu, nU, nI) {
  let s = 0;
  for (const r of data) {
    const pu = r.u*F, qi = r.i*F;
    let dot = 0;
    for (let f=0;f<F;f++) dot += P[pu+f]*Q[qi+f];
    const p = Math.min(5, Math.max(1, mu+dot));
    const d = p - r.r; s += d*d;
  }
  return Math.sqrt(s/data.length);
}
const data = [];
for (let k=0;k<2000;k++){
  const u = 1 + (k % 20);
  const i = 1 + ((k*7) % 50);
  data.push({u,i,r: 3 + Math.sin(u)*2 + Math.cos(i)});
}
const mu = data.reduce((a,x)=>a+x.r,0)/data.length;
let P = new Float32Array(21*F), Q = new Float32Array(51*F);
for (let k=0;k<P.length;k++) P[k]=(Math.random()*2-1)*0.05;
for (let k=0;k<Q.length;k++) Q[k]=(Math.random()*2-1)*0.05;
console.log("start", rmse(data,P,Q,mu,21,51).toFixed(4));
const lr=0.02, reg=0.02;
for (let ep=0; ep<200; ep++){
  for (const r of data){
    const pu=r.u*F, qi=r.i*F; let dot=0;
    for(let f=0;f<F;f++) dot+=P[pu+f]*Q[qi+f];
    const err=(mu+dot)-r.r;
    for(let f=0;f<F;f++){
      const pf=P[pu+f], qf=Q[qi+f];
      P[pu+f]=pf-lr*(err*qf+reg*pf);
      Q[qi+f]=qf-lr*(err*pf+reg*qf);
    }
  }
  if (ep%50===0||ep===199) console.log("ep",ep,"train RMSE",rmse(data,P,Q,mu,21,51).toFixed(4));
}
