const fs = require("fs"), path = require("path"), vm = require("vm");
const WEEK5 = "/home/neferpitu/recsys/RS/RecSys-LLMs/week5";

global.tf = require("@tensorflow/tfjs");
global.window = {};
const els = {};
function fakeEl() {
  return { innerHTML: "", textContent: "", className: "", value: "", addEventListener() {}, insertBefore() {} };
}
global.document = {
  getElementById: (id) => (els[id] || (els[id] = fakeEl())),
  createElement: () => fakeEl(),
  body: { insertBefore() {}, firstChild: null },
};
global.fetch = async (url) => ({ ok: true, text: async () => fs.readFileSync(path.join(WEEK5, url), "utf8") });

const source =
  fs.readFileSync(path.join(WEEK5, "data.js"), "utf8") + "\n" +
  fs.readFileSync(path.join(WEEK5, "script.js"), "utf8") + `
globalThis.__s = {
  get trainSet(){return trainSet}, get valSet(){return valSet}, get testSet(){return testSet},
  get movies(){return movies}, get ratings(){return ratings},
  get model(){return model}, get bestCheckpoint(){return bestCheckpoint},
  get trainingHistory(){return trainingHistory},
  get ratingStats(){return ratingStats}, get trainPool(){return TRAIN_POOL_EXCLUSIONS},
  runTests, initializeFactorsJS, trainMFJS, selectBestCheckpoint,
  computeBaselineRMSE, renderMetrics, renderAnalytics, recallAtK, recommendTopK,
  renderDatasetSummary, renderSplitSummary, renderTrainingCurve,
};
`;
vm.runInThisContext(source, { filename: "combined.js" });

(async () => {
  await tf.ready();
  await global.window.onload();
  const S = globalThis.__s;

  console.log("=== summary ===");
  console.log("movies", S.movies.length, "ratings", S.ratings.length,
    "sparsity", (S.ratingStats.sparsity * 100).toFixed(2) + "%");
  console.log("moviesNotInTrain", S.trainPool.moviesNotInTrain.length,
    "usersNotInTrain", S.trainPool.usersNotInTrain.length,
    "skippedUsers", (typeof SPLIT_EXCLUSIONS !== "undefined" ? "" : ""));

  console.log("\n=== self-checks ===");
  const res = S.runTests({ set textContent(v) { console.log(v.split("\n")[0]); } });
  console.log("=>", res.passed, "pass /", res.failed, "fail /", res.pending, "pending");

  console.log("\n=== pure JS SGD (default config: 20 ep, lr .01, reg .05, bs 64) ===");
  S.initializeFactorsJS(S.trainSet, 16);
  S.trainingHistory = S.trainMFJS(S.trainSet, S.valSet, { epochs: 20, lr: 0.01, reg: 0.05, batchSize: 64 }, S.testSet);
  // bestCheckpoint is module-level; emulate runPipeline
  vm.runInThisContext("bestCheckpoint = selectBestCheckpoint(trainingHistory);", { filename: "setbest.js" });
  const best = S.bestCheckpoint;
  const baseline = S.computeBaselineRMSE(S.testSet);
  console.log("baseline test RMSE", baseline.toFixed(4), "| MF test RMSE", best.testRMSE.toFixed(4),
    "| val", best.valRMSE.toFixed(4), "| best epoch", best.epoch, "| beats:", best.testRMSE < baseline);
  const rec = S.recallAtK(10);
  console.log("Recall@10", rec.overallRecall.toFixed(4), "evalUsers", rec.perUser.length,
    "unseenIds", rec.excluded.unseenIds.length, "withoutRelevant", rec.excluded.usersWithoutRelevant.length);

  console.log("\n=== renderers ===");
  S.renderDatasetSummary();
  S.renderSplitSummary();
  S.renderTrainingCurve();
  S.renderMetrics();
  S.renderAnalytics();
  for (const id of ["dataset-summary-body", "split-summary-body", "metrics-body"]) {
    const txt = (els[id].innerHTML || "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
    console.log(`[${id}]`, txt.slice(0, 260));
  }
  const an = (els["analytics-body"].innerHTML || "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
  console.log("[analytics-body]", an.slice(0, 500));
})().catch((e) => { console.error("FINAL ERROR", e); process.exit(1); });

